package it.frociart.app;
import android.app.Activity;import android.graphics.Typeface;import android.text.*;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import java.util.*;import java.util.function.Consumer;
/** A single frozen-frame calculation, owned by the variables inspector. */
final class FlowEvaluatePanel {
 static final class State {final FlowInspectExpression.Context context;final String draft;final int start,end;final boolean evaluated,fullOpen;final int fullScroll;State(FlowEvaluatePanel p){context=p.context;draft=p.expression.getText().toString();start=p.expression.getSelectionStart();end=p.expression.getSelectionEnd();evaluated=p.evaluated;fullOpen=p.readingSheet!=null&&p.readingSheet.dialog.isShowing();fullScroll=fullOpen?p.readingSheet.scroll.getScrollY():0;}}
 final Ui.Sheet sheet;final EditText expression;final TextView status,resultText;final Ui.Button copy,read;final FlowInspectExpression.Context context;private final TextView frameLabel,expressionLabel;
 private final Activity owner;private final Consumer<String> writer;private final Set<Ui.Sheet> children=new LinkedHashSet<>();private Ui.Sheet readingSheet;private FlowInspectExpression.Result result;private boolean evaluated,closed;
 FlowEvaluatePanel(Activity owner,Ui.Sheet sheet,FlowInspectExpression.Context context,String draft,Consumer<String> writer){
  this.owner=owner;this.sheet=sheet;this.context=context;this.writer=writer;
  LinearLayout form=Ui.column(owner);frameLabel=Ui.note(owner,context.functionName+" · passo "+context.steps+" · valori in pausa");form.addView(frameLabel);expressionLabel=Ui.text(owner,"ESPRESSIONE",11,true);Ui.pad(expressionLabel,0,10,0,8);form.addView(expressionLabel);LinearLayout entry=Ui.row(owner);expression=Ui.edit(owner,draft==null?"":draft,"Esempio: totale / quantità",false);expression.setContentDescription("Espressione da valutare sui valori in pausa");expression.setTag("inspection-expression");expression.setFilters(new InputFilter[]{new InputFilter.LengthFilter(8192)});expression.setImeOptions(EditorInfo.IME_ACTION_DONE|EditorInfo.IME_FLAG_NO_EXTRACT_UI);entry.addView(expression,Ui.weight(owner,-2));Ui.Button evaluate=new Ui.Button(owner,"Valuta",null,1);evaluate.setOnClickListener(v->calculate());LinearLayout.LayoutParams evaluateSize=new LinearLayout.LayoutParams(-2,-2);evaluateSize.leftMargin=Ui.dp(owner,8);entry.addView(evaluate,evaluateSize);form.addView(entry);sheet.fixed(form);sheet.paragraph("Calcola sui valori in pausa. Puoi usare le funzioni integrate; funzioni del programma e numeri casuali non vengono eseguiti.");sheet.root.getViewTreeObserver().addOnGlobalLayoutListener(keyboardLayout);
  status=Ui.note(owner,"Scrivi un’espressione, poi premi Valuta. Puoi usare variabili, indici e funzioni integrate.");status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);Ui.pad(status,0,10,0,10);sheet.body.addView(status);resultText=Ui.text(owner,"",15,false);resultText.setTypeface(Typeface.MONOSPACE);resultText.setTextIsSelectable(true);resultText.setTag("inspection-result");Ui.pad(resultText,12,12,12,12);Ui.card(resultText,Ui.bg(),14);sheet.body.addView(resultText,new LinearLayout.LayoutParams(-1,-2));
  read=sheet.action("Valore completo",null,0,this::readResult);copy=sheet.action("Copia risultato","duplicate",0,this::copyResult);read.setEnabled(false);copy.setEnabled(false);
  expression.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int n){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){result=null;evaluated=false;resultText.setText("");read.setEnabled(false);copy.setEnabled(false);status.setTextColor(Ui.muted());status.setText("Premi Valuta per aggiornare il risultato.");}});expression.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_DONE||(event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_DOWN)){calculate();return true;}return false;});
 }
 State snapshot(){return new State(this);}void restore(State state){if(state==null)return;expression.setText(state.draft);expression.setSelection(Math.max(0,Math.min(expression.length(),state.start)),Math.max(0,Math.min(expression.length(),state.end)));if(state.evaluated)calculate();if(state.fullOpen&&result!=null&&result.copyText!=null){readResult();final Ui.Sheet shown=readingSheet;shown.scroll.post(()->{if(!closed&&shown.dialog.isShowing())shown.scroll.scrollTo(0,state.fullScroll);});}}
 void calculate(){if(closed)return;evaluated=true;Ui.dismissKeyboard(expression);try{result=context.evaluate(expression.getText().toString());resultText.setText(result.preview);status.setTextColor(Ui.muted());status.setText(result.note.isEmpty()?"Valutazione completata. Il programma non è stato modificato.":result.note);read.setEnabled(result.copyText!=null);copy.setEnabled(result.copyText!=null);}catch(IllegalArgumentException error){result=null;resultText.setText("");read.setEnabled(false);copy.setEnabled(false);status.setTextColor(Ui.danger());status.setText(error.getMessage());}sheet.scroll.post(()->{if(!closed)sheet.scroll.smoothScrollTo(0,status.getTop());});}
 void copyResult(){if(result==null||result.copyText==null)return;try{writer.accept(result.copyText);status.setTextColor(Ui.muted());status.setText("Risultato copiato.");}catch(RuntimeException failed){status.setTextColor(Ui.danger());status.setText("Non riesco a copiare ora. Puoi riprovare o selezionare il valore completo.");}}
 void readResult(){if(closed||result==null||result.copyText==null)return;Ui.Sheet child=new Ui.Sheet(owner,"Valore completo",null);children.add(child);readingSheet=child;TextView text=Ui.text(owner,FlowInspectExpression.readable(result),15,false);text.setTypeface(Typeface.MONOSPACE);text.setTextIsSelectable(true);child.body.addView(text);child.dialog.setOnDismissListener(d->{children.remove(child);if(readingSheet==child)readingSheet=null;});child.show();}
 private final ViewTreeObserver.OnGlobalLayoutListener keyboardLayout=this::updateKeyboardLayout;
 private void updateKeyboardLayout(){if(closed)return;android.graphics.Rect visible=new android.graphics.Rect();sheet.root.getWindowVisibleDisplayFrame(visible);boolean shortSpace=visible.height()<Ui.dp(owner,330),ime=false;if(android.os.Build.VERSION.SDK_INT>=30){WindowInsets insets=sheet.dialog.getWindow().getDecorView().getRootWindowInsets();ime=insets!=null&&insets.isVisible(WindowInsets.Type.ime());}else ime=owner.getResources().getDisplayMetrics().heightPixels-visible.height()>Ui.dp(owner,100);boolean compact=shortSpace&&ime;sheet.compactHeader(compact||owner.getResources().getConfiguration().screenHeightDp<440);int visibility=compact?View.GONE:View.VISIBLE;if(frameLabel.getVisibility()!=visibility){frameLabel.setVisibility(visibility);expressionLabel.setVisibility(visibility);sheet.scroll.setVisibility(visibility);}}
 void close(){if(closed)return;closed=true;if(sheet.root.getViewTreeObserver().isAlive())sheet.root.getViewTreeObserver().removeOnGlobalLayoutListener(keyboardLayout);for(Ui.Sheet child:new ArrayList<>(children))child.dismissNow();children.clear();Ui.dismissKeyboard(expression);}
}
